    int k = 0;
    for (vector<int> g: graphs) {
        for (int i = 0; i < sn; ++i) {
            h[i] = g[i];
        }
        for (auto d: calc_degs(h, n)) {
            dgs[k++] = d*100;
        }
    }
    int ijs[sn];
